-- A column made `NOT NULL` by a primary key added after the table takes the identity
-- clause.
-- @profile-lock
-- @setup
CREATE TABLE ai (c SMALLINT, v TEXT);
INSERT INTO ai VALUES (7, 'seven');
ALTER TABLE ai ADD PRIMARY KEY (c);
ALTER TABLE ai ALTER COLUMN c ADD GENERATED BY DEFAULT AS IDENTITY;
INSERT INTO ai (v) VALUES ('minted');
-- @test
SELECT c, v FROM ai ORDER BY c;
